const apiKey = $input.first().json.body.api_key;
if (!apiKey || apiKey !== $env.N8N_API_KEY) throw new Error('Unauthorized');
const body = $input.first().json.body;
if (!body.brand_id) throw new Error('Missing brand_id');
return [{
  json: {
    brand_id: body.brand_id,
    topic_id: body.topic_id || '',
    topic_title: body.topic_title || '',
    post_id: body.post_id || '',
    mode: body.mode || 'create',
    log_id: 'cg-' + $now.toISO().replace(/[^0-9]/g, '').slice(0, 17),
    started_at: $now.toISO()
  }
}];

const brand = $('讀取品牌').first().json;
const topics = $('讀取已核准主題').all().map(i => i.json);
const optimization = $('讀取優化建議').first()?.json || {};
const req = $('驗證請求').first().json;

if (topics.length === 0) {
  throw new Error('沒有主題可以用來生成貼文');
}

// 優先用 topic_title 從 webhook payload（fan-out 時傳入），否則用 sheet 讀到的
const topicTitle = req.topic_title || (topics[0]?.topic_title || '');
const brandRelevance = topics[0]?.brand_relevance || '';
const suggestedAngles = topics[0]?.suggested_angles || '';
const contentType = topics[0]?.content_type || '知識長文';
const targetReader = topics[0]?.target_reader || brand.target_audience || '';

const topicsText = topics.slice(0, 5).map((t, i) =>
  `${i + 1}. ${t.topic_title}（來源：${t.source_url}）\n   品牌關聯：${t.brand_relevance || '無'}\n   建議角度：${t.suggested_angles || '無'}`
).join('\n');

const optimizationHint = optimization.caption_guidelines
  ? `\n\n上週優化建議：\n文案：${optimization.caption_guidelines}\n圖片：${optimization.image_guidelines || '無'}`
  : '';

const wingStyleRules = `你是 Wing 的個人撰文夥伴。Wing 是台灣的講師和自學顧問（數位顧問），為自由工作者、一人公司老闆、想斜槓的上班族撰寫 Facebook 商業貼文。

━━━ Wing 的聲音六原則 ━━━
1. 溫暖有觀點：友善但有立場。不說教，但不模糊。
2. 對比句：最愛的句式「不是 X，而是 Y」「不是你不夠努力，而是…」
3. 虛構人物：用 Paul、Alex、Irene 等虛構客戶讓抽象想法具體化，給他們職業
4. 第二人稱：全文用「你」稱呼讀者，不斷拉讀者進來
5. 口語括號：用括號加插話（嗯？）（應該吧...）（對吧？）
6. 數字錨定：用具體數字「一週 6 位數」「3-5 年」「每月省 20 小時」

━━━ 視覺格式（必須嚴格遵守）━━━
- 段落之間用 ​（零寬空白）隔開，不用空白行
- 重大段落分隔用單獨一行「-」
- 小標題用「▋ 」開頭
- 列點用「．」開頭
- Emoji 自然點綴，每篇 1-3 個

━━━ 知識長文結構 ━━━
【 挑釁性標題 】
​
[開場：虛構客戶場景]
​
-
​
▋ [問題根源]
​
[分析 + 對比句]
​
-
​
▋ [解法/框架]
​
[3個．列點]
​
-
​
▋ [兩個未來對比]
​
[一個讓人停下來的問題]
​
-
​
[溫暖收尾 + 服務提示]
💬 私訊「自動化」了解更多`;

return [{
  json: {
    brand,
    topics,
    prompt: `${wingStyleRules}

━━━ 品牌資料 ━━━
品牌名稱：${brand.brand_name}
品牌主題：${brand.theme}
風格：${brand.style || '專業、知識、科技感'}
語調：${brand.tone || '親切實用'}
目標受眾：${brand.target_audience}
過去內容範例：${brand.past_content_samples || '無'}${optimizationHint}

━━━ 本次主題 ━━━
${topicsText}

━━━ 你的任務 ━━━
針對上面每個主題，各產出 1 篇符合 Wing 風格的貼文。
以 JSON 陣列回傳，每個項目包含：
- topic_id: 對應的主題 ID
- caption: 完整貼文文字（繁體中文，含 hashtag，300-600 字，嚴格套用上方格式規則）
- image_prompt: 用於 AI 生圖的英文提示詞（具體描述風格、構圖、色彩，呼應品牌主色 ${brand.primary_color || '#2A4189'} 和輔色 ${brand.secondary_color || '#C67E13'}）
- platform: "both"

只回傳 JSON 陣列，不要 markdown 包裹。`
  }
}];

const brandId = $('驗證請求').first().json.brand_id;
const response = $input.first().json;
const content = response.candidates?.[0]?.content?.parts?.[0]?.text || '[]';

let posts;
try {
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  posts = JSON.parse(cleaned);
} catch (e) {
  throw new Error('AI 回傳格式解析失敗: ' + e.message);
}

const now = new Date().toISOString();

return posts.map((p, i) => ({
  json: {
    post_id: `post-${Date.now()}-${i}`,
    brand_id: brandId,
    topic_id: p.topic_id || '',
    platform: p.platform || 'both',
    caption: p.caption || '',
    image_prompt: p.image_prompt || '',
    image_url: '',
    scheduled_time: '',
    status: 'draft',
    fb_post_id: '',
    ig_post_id: '',
    optimization_version: '0',
    created_at: now
  }
}));

// 將已使用的主題標記為 used
const posts = $('解析貼文').all().map(i => i.json);
const topicIds = [...new Set(posts.map(p => p.topic_id).filter(Boolean))];

return topicIds.map(id => ({ json: { topic_id: id, status: 'used' } }));

// 產生 Wing Style 知識圖卡並上傳到 imgbb
const FALLBACK_IMG = 'https://i.ibb.co/VchfbRqg/content.jpg';
const IMGBB_KEY = $env.IMGBB_API_KEY || '';
const GEMINI_KEY = $env.GEMINI_API_KEY || '';
const IS_MOCK = String($env.MOCK_GEMINI || '').toLowerCase() === 'true';
const req = $('驗證請求').first().json;
const topicTitle = req.topic_title || '';

const WING_STYLE = `你是 Wing Style 圖片產生器。根據使用者提供的文字，生成知識圖卡。\n\n視覺風格：\n- 主色(背景底色)：深藍色 (#2A4189) 或深色漸層\n- 文字與裝飾色：白色 (#FFFFFF)、亮藍色或淺灰色，確保高對比度\n- 重點色：黃橙色 (#FDBD3B) 標示標題或關鍵資訊\n- 設計風格：扁平化 (Flat design) 向量插圖，商務、科技與專業感\n- 比例保持 16:9\n\n版面佈局：\n- 頂部標題區塊，輔以外框、引號或裝飾邊線\n- 模組化網格或分欄佈局，不同主題放在帶細邊框的矩形面板中\n- 每個面板遵循「圖示/插圖 + 小標題 + 簡短說明」組合\n- 使用數字編號或箭頭引導視覺動線\n\n輸出語言一律使用繁體中文，追求最高解析度。`;

const results = [];
for (const item of $input.all()) {
  const post = item.json;
  let imageUrl = FALLBACK_IMG;

  if (!IS_MOCK && GEMINI_KEY && IMGBB_KEY) {
    try {
      const caption = (post.caption || '').slice(0, 1500);
      const geminiRes = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash-exp:generateContent?key=${GEMINI_KEY}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            contents: [{ parts: [{ text: WING_STYLE + '\n\n以下是要轉成知識圖卡的文案內容：\n\n' + caption }] }],
            generationConfig: { responseModalities: ['IMAGE', 'TEXT'] }
          })
        }
      );
      const geminiData = await geminiRes.json();
      const imgPart = (geminiData?.candidates?.[0]?.content?.parts || []).find(p => p.inlineData);

      if (imgPart?.inlineData?.data) {
        const form = new URLSearchParams();
        form.append('key', IMGBB_KEY);
        form.append('image', imgPart.inlineData.data);
        const imgbbRes = await fetch('https://api.imgbb.com/1/upload', { method: 'POST', body: form });
        const imgbbData = await imgbbRes.json();
        if (imgbbData?.data?.url) imageUrl = imgbbData.data.url;
      }
    } catch (e) {
      // fallback to fixed image
    }
  }

  results.push({ json: { ...post, image_url: imageUrl, topic_title: topicTitle || post.topic_title || '' } });
}
return results;

// 拆兩列：一篇主題 → 一篇 FB + 一篇 IG
const out = [];
for (const item of $input.all()) {
  const base = item.json;
  const ts = Date.now();
  const rnd = Math.random().toString(36).slice(2, 7);
  for (const plat of ['facebook', 'instagram']) {
    out.push({ json: {
      ...base,
      post_id: base.post_id || `post-${ts}-${plat[0]}-${rnd}`,
      platform: plat
    } });
  }
}
return out;

